def transform_v3(grid):
    h, w = len(grid), len(grid[0])

    # 0 -> 1
    grid = [[1 if x == 0 else x for x in row] for row in grid]

    result = [[1 for _ in range(w)] for _ in range(h)]
    visited = [[False for _ in range(w)] for _ in range(h)]

    from collections import deque, Counter

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 and not visited[r][c]:
                # BFS for connected non-1 pixels
                component = []
                q = deque([(r, c)])
                visited[r][c] = True

                while q:
                    cr, cc = q.popleft()
                    component.append((cr, cc))

                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                            if grid[nr][nc] != 1:
                                visited[nr][nc] = True
                                q.append((nr, nc))

                # Count colors
                color_counts = Counter([grid[rr][cc] for rr, cc in component])

                # Rule: if component has only 1 pixel (size 1), make it 1
                # Otherwise, use dominant non-1 color
                if len(component) == 1:
                    val = 1
                else:
                    # Get dominant among non-1
                    non1_counts = {k: v for k, v in color_counts.items() if k != 1}
                    if non1_counts:
                        dominant = non1_counts.most_common(1)[0][0]
                        val = dominant
                    else:
                        val = 1

                for rr, cc in component:
                    result[rr][cc] = val

    return result

