def get_horizontal_same_color_components(grid):
    """Get components where pixels are adjacent in the same row."""
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    components = []
    visited = [[False for _ in range(w)] for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 and not visited[r][c]:
                component = []
                visited[r][c] = True

                # BFS only horizontally
                q = deque([(r, c)])
                while q:
                    r_curr, c_curr = q.popleft()
                    component.append((r_curr, c_curr))

                    for dc in [1, -1]:
                        nc = c_curr + dc
                        if 0 <= nc < w and not visited[r][nc]:
                            if grid[r][nc] == grid[r_curr][c_curr]:  # Same color, same row
                                visited[r][nc] = True
                                q.append((r, nc))

                components.append(component)

    return components

