# Let me try yet another approach:
# Rule: Same-color 4-connected components.
# - Multi-pixel: normalize to dominant color
# - Single-pixel (size 1): becomes 1 always (no absorption for isolated pixels)
# This means first mark all same-color 4-connected components
# Then only multi-pixel get normalized colors

def transform_simple(grid):
    from collections import deque, Counter

    h, w = len(grid), len(grid[0])

    # 0 -> 1
    grid = [[1 if x == 0 else x for x in row] for row in grid]

    visited = [[False for _ in range(w)] for _ in range(h)]
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    # Find all same-color components
    all_components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 and not visited[r][c]:
                comp = []
                q = deque([(r, c)])
                visited[r][c] = True
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                            if grid[nr][nc] == grid[cr][cc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))
                all_components.append(comp)

    # Mark components: single pixels become 1, multi-pixel normalize
    result = [[1 for _ in range(w)] for _ in range(h)]

    for comp in all_components:
        if len(comp) == 1:
            # Single pixel, stays 1 (will overwrite)
            continue
        else:
            # Multi-pixel component, normalize to dominant color
            color_counts = Counter([grid[cr][cc] for cr, cc in comp])
            non1_counts = {k: v for k, v in color_counts.items() if k != 1}
            if non1_counts:
                dominant = non1_counts.most_common(1)[0][0]
            else:
                dominant = 1
            for cr, cc in comp:
                result[cr][cc] = dominant

    return result

